#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/python/tasks/code-lint-ruff.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Lint the Python files with ruff"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--all" help="lint every file of the repository, not only the uncommitted files"
# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--fix" help="apply fixes"
# USAGE arg "[files]" var=#true help="the files to lint; only the .py and .pyi files are used; the default is the uncommitted files"
# FILES include="*.py *.pyi" exclude=".config/mise/tasks/**"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# Shipped with the python tool. The sync installs ruff only in a repository
# with a pyproject.toml. Without ruff, the task does not apply and prints
# nothing.
if not helpers.has_tool("ruff"):
  sys.exit(0)
os.chdir(os.environ["MISE_PROJECT_ROOT"])

# code:lint passes its flags and files to each code:lint:* task. The list
# comes from gate_files (the # FILES header above). An empty list: nothing
# to do.
args = [f"--{flag}" for flag in ("all", "debug", "fix") if os.environ.get(f"usage_{flag}") == "true"]
listing = helpers.gate_files(__file__, *args, *helpers.usage_files())
try:
  if os.path.getsize(listing) == 0:
    sys.exit(0)

  options = []
  if os.environ.get("usage_fix") == "true":
    options.append("--fix")
  if os.environ.get("usage_debug") == "true":
    options.append("--verbose")

  helpers.print_header("Linting the Python files with ruff ...")
  # xargs gives the list to the tool, as each gate does.
  with open(listing, "rb") as f:
    files = f.read().replace(b"\n", b"\0")
  result = subprocess.run(["xargs", "-0", "mise", "x", "--", "ruff", "check", *options], input=files, check=False)
  sys.exit(result.returncode)
finally:
  os.remove(listing)
